package com.chedidandrew.emeraldstandard.neoforge;
import com.chedidandrew.emeraldstandard.core.*; import net.minecraft.world.level.storage.LevelResource; import net.neoforged.bus.api.SubscribeEvent; import net.neoforged.fml.common.Mod; import net.neoforged.neoforge.common.NeoForge; import net.neoforged.neoforge.event.RegisterCommandsEvent; import net.neoforged.neoforge.event.server.*; import net.neoforged.neoforge.event.tick.ServerTickEvent;
@Mod(EmeraldStandardNeoForge.MODID) public final class EmeraldStandardNeoForge { public static final String MODID="the_emerald_standard"; private static final EconomyService ECON=new EconomyService(); public EmeraldStandardNeoForge(){NeoForge.EVENT_BUS.register(this);} @SubscribeEvent public void started(ServerStartedEvent ev){try{var s=ev.getServer();long t=s.overworld().getGameTime();ECON.start(s.getWorldPath(LevelResource.DATA),s.overworld().getSeed(),t);}catch(Exception e){throw new RuntimeException(e);}} @SubscribeEvent public void stop(ServerStoppingEvent e){ECON.saveQuiet();} @SubscribeEvent public void tick(ServerTickEvent.Post e){ECON.tick(e.getServer().overworld().getGameTime());} @SubscribeEvent public void commands(RegisterCommandsEvent e){EmeraldCommands.register(e.getDispatcher(),ECON);} }
